#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST"
echo ">> destino: $DEST"
echo "" | base64 -d > "$DEST/ecc_fw.s"
echo "" | base64 -d > "$DEST/fw_oracle.py"
echo "" | base64 -d > "$DEST/gen_layer4.py"
echo "" | base64 -d > "$DEST/ecc_soc_top.vhd"
echo "" | base64 -d > "$DEST/tb_layer4.vhd"
echo "" | base64 -d > "$DEST/tb_layer4_b.vhd"
echo "" | base64 -d > "$DEST/ecc_regbank.vhd"
echo "MDAwMDAwMDEK" | base64 -d > "$DEST/cfg_a.txt"
echo "MDAwMDAwMDAK" | base64 -d > "$DEST/cfg_b.txt"
echo ">> ensamblando firmware con asm.py (debe estar en ~/rv32i/asm.py o local)"
ASM="${ASM:-$HOME/rv32i/asm.py}"
[ -f "$ASM" ] || ASM="$DEST/asm.py"
( cd "$DEST" && python3 "$ASM" ecc_fw.s ecc_fw.mem >/dev/null && echo "   firmware: $(wc -l < ecc_fw.mem) instr" )
echo ">> generando init + expected de Layer 4"
( cd "$DEST" && python3 gen_layer4.py )
echo ">> NOTA: copia los fuentes del RV32 (riscv_pkg, cpu_pipeline, alu, control,"
echo "   immgen, regfile, csr, muldiv, dp_ram) a $DEST o ajusta las rutas de analisis."
echo ">> analizando y corriendo Layer 4 (requiere fuentes RV32 presentes)"
( cd "$DEST" && rm -rf work-obj08.cf && \
  ghdl -a --std=08 riscv_pkg.vhd alu.vhd control.vhd immgen.vhd regfile.vhd csr.vhd \
    muldiv.vhd cpu_pipeline.vhd dp_ram.vhd ecc_pkg.vhd ecc_codec.vhd scrub_bram.vhd \
    scrub_fsm.vhd ecc_regbank.vhd ecc_soc_top.vhd tb_layer4.vhd tb_layer4_b.vhd 2>/dev/null && \
  echo "   RUN A:" && ghdl -r --std=08 tb_layer4   --stop-time=500us 2>&1 | grep -oE "LAYER4 RUN A (PASS|FAIL)" && \
  echo "   RUN B:" && ghdl -r --std=08 tb_layer4_b --stop-time=500us 2>&1 | grep -oE "LAYER4 RUN B (PASS|FAIL)" ) || \
  echo "   (si fallo el analisis, faltan los fuentes RV32 en $DEST)"
